    brief: 'Stay close behind the teal courier van',
    reward: 400,
    target: 'courier',
    kind: 'tail',
  },
  {
    id: 4,
    name: 'Heat Run',
    giver: 'Marla Vane',
    intro: 'The Shores PD put a price on that sedan. Make some noise, get the heat on you, then shake it and meet me at the Pier. If you can.',
